/**
 * gpr-country-data — server-side accessor for the per-country GPR layer.
 *
 * Reads the build-time data/gpr-country.json (generated by
 * scripts/generate_gpr_country_json.py). Only the 44 countries with a
 * published academic benchmark carry an entry; every other country returns
 * null, so the country-page panel renders for the validated set only and is
 * cleanly absent everywhere else (confidence-first: no placeholder).
 */
import gpr from "@/data/gpr-country.json";

export type GprTier = "A" | "B" | "C";

export interface GprCountryEntry {
  iso3: string;
  name: string;
  validated: boolean;
  tier: GprTier;
  tier_label: string;
  delta_spearman: number;
  spike_recall: number;
  n_months: number;
  window: string;
  /** Ascending monthly QGI-GPR movement series (0-1 proxy values). */
  series: { dates: string[]; values: number[] };
}

const COUNTRIES = (gpr as { countries: Record<string, GprCountryEntry> }).countries;

/** The GPR entry for an ISO3 code, or null when the country has no coverage. */
export function getGprEntry(iso3: string): GprCountryEntry | null {
  if (!iso3) return null;
  return COUNTRIES[iso3.toUpperCase()] ?? null;
}
